def compute(vars):
    loan = vars["v1"]
    total_assets_pledged = vars["v2"]

    if total_assets_pledged == 0:
        return None

    percentage = (loan / total_assets_pledged) * 100

    return {
        "value": percentage,
        "trace": {
            "loan": loan,
            "total_assets_pledged": total_assets_pledged,
            "output_meta": {
                "currency": None,
                "scale": "billion",
                "unit": "percentage"
            }
        }
    }
